import { HomeMain } from '../../slots/defs/homeMain';
import { VoidReasons } from './VoidReasons';

export const contribution = HomeMain.fill({ order: 9.75, Component: VoidReasons });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** The query key for the sheet's void reasons; under sheetKey, so re-loading the sheet re-reads them. */
export const voidReasonsKey = (sheet: string) => [...sheetKey(sheet), 'void-reasons'] as const;

/**
 * The sheet's void reasons, in the order they were added. While the list is not empty, a claim is voided only with a
 * reason chosen from it.
 */
export function useVoidReasons() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: voidReasonsKey(sheet),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`),
    enabled: !!sheet,
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useVoidReasons, voidReasonsKey } from './voidReasons';
import { useOneAtATime } from '../../query/useOneAtATime';

// The sheet's void reasons and the entry a reason is added to them with; a blank reason or one already on the list is
// refused.
export function VoidReasons() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const reasons = useVoidReasons().data ?? [];
  const [text, setText] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: { reason: string }) =>
      postJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons?user=${encodeURIComponent(user)}`, input),
    onSuccess: async (saved) => {
      setText('');
      setError('');
      queryClient.setQueryData(voidReasonsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheet) });
    },
    onError: () => setError('That void reason was refused: it is blank or already on the list.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const reason = text.trim();
    if (!reason) {
      setError('Type the void reason.');
      return;
    }
    if (reasons.includes(reason)) {
      setError(`${reason} is already a void reason.`);
      return;
    }
    once(() => add.mutateAsync({ reason }));
  };

  return (
    <section data-testid="void-reasons">
      <ul data-testid="void-reason-list">
        {reasons.map((r) => (
          <li key={r} data-testid={`void-reason-row-${r}`}>
            {r}
          </li>
        ))}
      </ul>
      <form onSubmit={submit} data-testid="void-reason-form">
        <input
          data-testid="void-reason-text"
          placeholder="Void reason"
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            setError('');
          }}
        />
        <button type="submit" data-testid="void-reason-add" disabled={add.isPending}>
          Add void reason
        </button>
        {error && <span data-testid="void-reason-error">{error}</span>}
      </form>
    </section>
  );
}
import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Person } from '../people/people';
import { SIGNED_AMOUNT, claimsKey, useClaims } from './claims';
import type { Claim, ClaimInput } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';
import { setClaimError, useClaimError } from './claimError';
import { contains, usePeriods } from '../periods/periods';
import { useSettings } from '../settings/settings';
import { useSheetToday } from '../session/sheetToday';
import { tagsKey } from '../tags/tags';

const EMPTY: ClaimInput = { amount: '', date: '', note: '', corrects: '', ref: '', tags: '' };

// A person's claims, newest first, and the form that adds one — or, while a claim's editor is
// open, saves that claim's changes. Opening an editor (the edit button) locks the claim for every
// other user and fills the form with the claim's values; a refusal (not editable, a viewer, or
// locked by another user) shows as the claim's error. Saving or cancelling the editor releases the
// lock. A claim the signed-in user holds the lock on comes back with its editor open when the sheet
// is loaded again. A refusal the screen can see (not a DRAFT, due by a date in a closed period, a viewer, locked
// by another user) shows at once; otherwise the editor opens at once and the lock is taken behind it —
// a save waits for it, and a refused lock closes the editor and shows the claim's error.
export function PersonClaims({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  const [form, setForm] = useState<ClaimInput>(EMPTY);
  const [editing, setEditing] = useState<number | undefined>(undefined);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();
  const periods = usePeriods().data ?? [];
  const settings = useSettings().data;
  const today = useSheetToday();
  // A viewer refused editing, unless a delegation in force on the sheet's today makes them a steward.
  const viewer =
    (settings?.roles ?? []).some((r) => r.user === user && r.role === 'viewer') &&
    !(settings?.delegations ?? []).some((d) => d.user === user && d.from <= today && today <= d.to);
  const editingNow = useRef<number | undefined>(undefined);
  editingNow.current = editing;
  const locking = useRef<Promise<void>>(Promise.resolve());

  const claimsUrl = `/api/sheets/${encodeURIComponent(sheet)}/claims`;

  // Show the claim as (un)locked by the user at once, so a released lock does not re-open its editor.
  const markLocked = (id: number, lockedBy: string | null) =>
    queryClient.setQueryData<Claim[]>(claimsKey(sheet), (all) => all?.map((c) => (c.id === id ? { ...c, lockedBy } : c)));

  const release = (id: number) => {
    markLocked(id, null);
    postJson<Claim>(`${claimsUrl}/${id}/unlock?user=${encodeURIComponent(user)}`, {}).catch(() => undefined);
  };

  const close = () => {
    if (editing !== undefined) release(editing);
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const fill = (c: Claim) => {
    setEditing(c.id);
    setForm({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '', tags: c.tags.join(', ') });
    setError('');
  };

  const save = useMutation({
    mutationFn: async (input: ClaimInput) => {
      if (editing === undefined) {
        return postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/claims?user=${encodeURIComponent(user)}`, input);
      }
      await locking.current;
      return putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${editing}?user=${encodeURIComponent(user)}`, input);
    },
    onSuccess: async () => {
      if (editing !== undefined) markLocked(editing, null);
      setEditing(undefined);
      setForm(EMPTY);
      setError('');
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: tagsKey(sheet) }),
      ]);
    },
    onError: () => setError('That claim could not be saved.'),
  });

  const refused = (c: Claim) =>
    `This ${c.status} claim cannot be edited (only a DRAFT not due in a closed period, not by a viewer, nor while another user is editing it).`;

  // Why the edit button is refused, from what the screen holds; '' when the server is asked.
  const refusal = (c: Claim) =>
    c.status !== 'DRAFT' ||
    viewer ||
    (c.lockedBy !== null && c.lockedBy !== user) ||
    periods.some((p) => p.closed && contains(p, c.dueBy))
      ? refused(c)
      : '';

  // Re-open the editor of a claim the user still holds the lock on (the sheet was loaded again).
  const held = editing === undefined ? claims.find((c) => c.lockedBy === user) : undefined;
  useEffect(() => {
    if (held) fill(held);
  }, [held?.id]);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!SIGNED_AMOUNT.test(form.amount.trim())) {
      setError('Type an amount with at most two decimals.');
      return;
    }
    const date = form.date.trim();
    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const edit = (c: Claim) => {
    const why = refusal(c);
    setClaimError(sheet, c.id, why);
    if (why) return;
    if (editing !== undefined) release(editing);
    markLocked(c.id, user);
    fill(c);
    const taken = postJson<Claim>(`${claimsUrl}/${c.id}/lock?user=${encodeURIComponent(user)}`, {}).then(
      () => undefined,
      async (e) => {
        markLocked(c.id, null);
        if (editingNow.current === c.id) {
          setEditing(undefined);
          setForm(EMPTY);
          setError('');
        }
        setClaimError(sheet, c.id, refused(c));
        await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
        throw e;
      },
    );
    taken.catch(() => undefined);
    locking.current = taken;
  };

  return (
    <td data-testid="person-claims">
      <ul>
        {claims.map((c) => (
          <li key={c.id} data-testid={`claim-row-${c.id}`}>
            <span data-testid="claim-amount">{c.amount}</span> <span data-testid="claim-date">{c.date}</span>{' '}
            <span data-testid="claim-note" style={{ whiteSpace: 'pre' }}>
              {c.note}
            </span>{' '}
            <ClaimRowValues.Slot claim={c} person={person} />{' '}
            {editing === c.id ? (
              <button type="button" data-testid="claim-cancel" onClick={close}>
                Cancel
              </button>
            ) : (
              <button type="button" data-testid="claim-edit" onClick={() => edit(c)}>
                Edit
              </button>
            )}{' '}
            <ClaimInlineAmount claim={c} refusal={refusal(c)} />
          </li>
        ))}
      </ul>
      <form onSubmit={submit} data-testid="claim-form">
        <input
          data-testid="claim-form-amount"
          placeholder="Amount"
          value={form.amount}
          onChange={(e) => change({ amount: e.target.value })}
        />
        <input
          data-testid="claim-form-date"
          placeholder="yyyy-mm-dd"
          value={form.date}
          onChange={(e) => change({ date: e.target.value })}
        />
        <input
          data-testid="claim-form-note"
          placeholder="Note"
          value={form.note}
          onChange={(e) => change({ note: e.target.value })}
        />
        <input
          data-testid="claim-form-corrects"
          placeholder="Corrects claim no."
          value={form.corrects}
          onChange={(e) => change({ corrects: e.target.value })}
        />
        <input
          data-testid="claim-form-ref"
          placeholder="Reference"
          value={form.ref}
          onChange={(e) => change({ ref: e.target.value })}
        />
        <input
          data-testid="claim-form-tags"
          placeholder="Tags, comma separated"
          value={form.tags}
          onChange={(e) => change({ tags: e.target.value })}
        />
        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
          {editing === undefined ? 'Add claim' : 'Save claim'}
        </button>
        {error && <span data-testid="claim-form-error">{error}</span>}
      </form>
    </td>
  );
}

// A claim's amount changed in its row: the entry and save button beside the edit button. The save is
// the editor's save with only the amount changed, so it follows the claim form's rules (and writes
// CLAIM_EDITED); a refusal shows as the claim's error, at once when the screen can see it.
function ClaimInlineAmount({ claim, refusal }: { claim: Claim; refusal: string }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setError] = useClaimError(claim.id);
  const [amount, setAmount] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (value: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}?user=${encodeURIComponent(user)}`, {
        amount: value,
        date: claim.date,
        note: claim.note,
        corrects: claim.corrects ?? '',
        ref: claim.ref ?? '',
        tags: claim.tags.join(','),
      }),
    onSuccess: async () => {
      setAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () => setError('That claim could not be saved.'),
  });

  return (
    <>
      <input
        data-testid="claim-inline-amount"
        placeholder="Amount"
        value={amount}
        onChange={(e) => {
          setAmount(e.target.value);
          setError('');
        }}
      />
      <button
        type="button"
        data-testid="claim-inline-save"
        disabled={save.isPending}
        onClick={() => {
          setError('');
          if (refusal) {
            setError(refusal);
            return;
          }
          const value = amount.trim();
          if (!SIGNED_AMOUNT.test(value)) {
            setError('Type an amount with at most two decimals.');
            return;
          }
          once(() => save.mutateAsync(value));
        }}
      >
        Save amount
      </button>
    </>
  );
}
import { useSyncExternalStore } from 'react';
import { useCurrentSheet } from '../session/session';

// One error per claim row, shared by every action on the row (a status change, a move, the edit button, ...): the
// row shows it once, and the next action on the row clears it.
const errors = new Map<string, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** The claim row's error ('' when none) and the setter every action on the row uses. */
export function useClaimError(claimId: number): [string, (message: string) => void] {
  const [sheet] = useCurrentSheet();
  const key = `${sheet}:${claimId}`;
  const error = useSyncExternalStore(subscribe, () => errors.get(key) ?? '');
  return [error, (message: string) => setClaimError(sheet, claimId, message)];
}

/** Set (or, with '', clear) the error of a claim row on the sheet. */
export function setClaimError(sheet: string, claimId: number, message: string) {
  const key = `${sheet}:${claimId}`;
  if (message) errors.set(key, message);
  else errors.delete(key);
  listeners.forEach((l) => l());
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { covers, liveHolds } from '../people/people';
import type { Hold } from '../people/people';
import { sheetKey, useCurrentSheet } from '../session/session';

/**
 * Where a claim is in its life: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit makes it
 * PENDING, which a steward approves (SETTLED) or rejects (OPEN); DRAFT, OPEN or PENDING -> VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** Whether a claim is open: OPEN, or PENDING (handled like an open claim). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim is deferred on the sheet's `today`: OPEN, deferred until a date after it. A deferred claim counts
 * in no total, is not overdue, cannot be settled and is left unbound by a statement.
 */
export const deferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== '' && today < c.deferredUntil;

/** Whether a statement binds the claim now: it was stated and is not PENDING (a pending claim shows its live figure). */
export const bound = (c: Claim) => c.stated && c.status !== 'PENDING';

/**
 * A claim as the store holds it: the amount with two decimals, the date as yyyy-MM-dd; its number
 * is the sheet's next one when it was opened (1, 2, ...; under period numbering, the next within its period (the one containing its due-by): P1-1, X-1), null while a draft (a voided claim keeps it); its due is the
 * one fixed when it was settled (two decimals), null while it is live; openedBy is the user who
 * opened it, null while a draft; stated is whether its person's last statement bound it to a figure,
 * statedDue that figure (two decimals; null: n/a) — it then shows and totals that, not its live figure;
 * corrects is, for a correction (a negative amount), the number of the settled claim it corrects, null otherwise;
 * dueBy (yyyy-MM-dd) is fixed when it was created: the terms-th business day after its date for the terms of its person
 * (else their grade's, else the sheet's) in force on it, skipping Saturdays, Sundays and the sheet's holidays then on the list;
 * log is its status log, oldest first: each status it has had, the user who gave it, the sheet's today then and its due then;
 * deferredUntil (yyyy-MM-dd) is the date it was deferred until, null when it never was;
 * proofs is how many proofs it has been given (a claim whose due is above the proof threshold in force on its date — its
 * person's grade's own, else the sheet's — is
 * settled or approved only once it has one);
 * splitFrom is the number of the claim it was split off, null when it was not split off one;
 * lockedBy is the user whose open editor locks it for every other user, null when it is not locked;
 * lateEntry is whether it was added while the period containing its due-by was soft-closed;
 * reminded (yyyy-MM-dd) is the last day a reminder was written for it, null when it never was;
 * ref is its external reference (unique on the sheet, ignoring case), null when it has none;
 * tags are its tags (lower-cased, no repeats), sorted; empty when it has none;
 * voidReason is the reason from the sheet's void reasons it was voided with, null when none;
 * comments are its comments, oldest first: the user who wrote each, the sheet's today then and its text;
 * batch is the number of the bulk settle batch that settled it (SETTLED or PENDING), null when it was settled one at a time or never.
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: ClaimLogLine[];
  deferredUntil: string | null;
  proofs: number;
  splitFrom: string | null;
  lockedBy: string | null;
  lateEntry: boolean;
  reminded: string | null;
  ref: string | null;
  tags: string[];
  voidReason: string | null;
  comments: ClaimComment[];
  batch: number | null;
};

/** A comment on a claim: the user who wrote it, the sheet's today then (yyyy-MM-dd) and its text. */
export type ClaimComment = { by: string; date: string; text: string };

import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonClaims } from './PersonClaims';

export const contributions = [
  PersonColumnHeads.fill({ order: 20, Component: () => <th>Claims</th> }),
  PersonColumns.fill({ order: 20, Component: PersonClaims }),
];

