            throws InvalidTemplateException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidTemplateException("A template's name is required.");
        }
        Out<ClaimInput> input = new Out<>() {
            ClaimInput value;

            @Override
            public void set(ClaimInput value) {
                this.value = value;
            }
        };
        ClaimInput[] valid = new ClaimInput[1];
        try {
            new ValidateClaimRequest().validate(new ClaimRequest(request.amount(), "", request.note(), "", "", ""),
                    value -> valid[0] = value);
        } catch (InvalidClaimException e) {
            throw new InvalidTemplateException(e.getMessage());
        }
        template.set(new ClaimTemplate(sheet.id(), name, valid[0].amount(), valid[0].note()));
    }
}
